import arcjet, { tokenBucket, shield } from '@arcjet/next';
import { NextRequest, NextResponse } from 'next/server';

const aj = arcjet({
  key: process.env.ARCJET_KEY!,
  characteristics: ['ip.src'],
  rules: [
    // Protect against common web attacks
    shield({ mode: 'LIVE' }),
    // Token bucket: 10 requests capacity, refills 10 per 60 seconds
    tokenBucket({
      mode: 'LIVE',
      refillRate: 10,
      interval: 60,
      capacity: 10,
    }),
  ],
});

export async function POST(req: NextRequest): Promise<NextResponse> {
  const decision = await aj.protect(req, { requested: 1 });

  if (decision.isDenied()) {
    if (decision.reason.isRateLimit()) {
      return NextResponse.json(
        { error: 'Too many requests. Please try again later.' },
        { status: 429 }
      );
    }
    if (decision.reason.isShield()) {
      return NextResponse.json(
        { error: 'Suspicious request blocked.' },
        { status: 403 }
      );
    }
    return NextResponse.json({ error: 'Forbidden.' }, { status: 403 });
  }

  // Request is allowed — proceed with handler logic
  const body: unknown = await req.json();
  return NextResponse.json({ ok: true, received: body });
}

import arcjet, { detectBot, validateEmail, shield } from '@arcjet/next';
import { NextRequest, NextResponse } from 'next/server';

const aj = arcjet({
  key: process.env.ARCJET_KEY!,
  characteristics: ['ip.src'],
  rules: [
    shield({ mode: 'LIVE' }),
    // Block bots — allow search engine crawlers
    detectBot({
      mode: 'LIVE',
      allow: ['CATEGORY:SEARCH_ENGINE', 'CATEGORY:MONITOR'],
    }),
    // Reject disposable/invalid email addresses
    validateEmail({
      mode: 'LIVE',
      block: ['DISPOSABLE', 'INVALID', 'NO_MX_RECORDS'],
    }),
  ],
});

interface SignupBody {
  email: string;
  name: string;
}

export async function POST(req: NextRequest): Promise<NextResponse> {
  const body = (await req.json()) as SignupBody;

  const decision = await aj.protect(req, { email: body.email });

  if (decision.isDenied()) {
    if (decision.reason.isEmail()) {
      return NextResponse.json(
        { error: 'Invalid or disposable email address. Please use a real email.' },
        { status: 422 }
      );
    }
    if (decision.reason.isBot()) {
      return NextResponse.json(
        { error: 'Automated signups are not allowed.' },
        { status: 403 }
      );
    }
    return NextResponse.json({ error: 'Signup blocked.' }, { status: 403 });
  }

  // Valid human with a real email — create the account
  return NextResponse.json({ ok: true, message: 'Account created.' });
}
